def calculate_a(n):
    a = {}
    for i in range(1, n + 1):
        if i == 1 or i == 2:
            a[i] = 1
        else:
            try:
                # Check if a_{i-1} is defined (always true if i >= 3)
                a_prev = a[i-1]
                # Check if a_{a_{i-1}} and a_{i - a_{i-1}} are defined
                if a_prev in a and (i - a_prev) in a:
                    a[i] = a[a_prev] + a[i - a_prev]
                else:
                    # This should not happen if a_n is always positive, which it is.
                    raise ValueError("Index out of bounds for sequence calculation.")
            except KeyError as e:
                print(f"Error calculating a_{i}: required index {e} missing.")
                return None
    return a

N = 12
sequence = calculate_a(N)
print("n | a_n")
for i in range(1, N + 1):
    print(f"{i} | {sequence[i]}")
